        "ta": "\u0B95\u0B9F\u0BB2\u0BCD \u0BB5\u0BB0\u0BCD\u0BA4\u09CD\u0BA4\u0B95\u0BAE\u0BCD",
        "te": "\u0C38\u0C2E\u0C41\u0C26\u0C4D\u0C30 \u0C35\u0C3E\u0C23\u0C3F\u0C1C\u0C4D\u0C2F\u0C02",
        "kn": "\u0CB8\u0CBE\u0C97\u0CB0 \u0CB5\u0CCD\u0CAF\u0CBE\u0CAA\u0CBE\u0CB0",
        "bn": "\u09B8\u09BE\u09AE\u09C1\u09A6\u09CD\u09B0\u09BF\u0995 \u09AC\u09BE\u09A3\u09BF\u099C\u09CD\u09AF",
        "as": "\u09B8\u09BE\u09AE\u09C1\u09A6\u09CD\u09F0\u09BF\u0995 \u09AC\u09BE\u09A3\u09BF\u099C\u09CD\u09AF",
