        "ta": "\u0BAE\u0B9A\u0BBE\u0BB2\u0BBE \u0BB5\u0BB0\u0BCD\u0BA4\u0BCD\u0BA4\u0B95\u0BAE\u0BCD",
        "te": "\u0C2E\u0C38\u0C3E\u0C32\u0C3E \u0C35\u0C3E\u0C23\u0C3F\u0C1C\u0C4D\u0C2F\u0C02",
        "kn": "\u0CAE\u0CB8\u0CBE\u0CB2\u0CC6 \u0CB5\u0CCD\u0CAF\u0CBE\u0CAA\u0CBE\u0CB0",
        "bn": "\u09AE\u09B6\u09B2\u09BE \u09AC\u09BE\u09A3\u09BF\u099C\u09CD\u09AF",
        "as": "\u09AE\u099A\u09B2\u09BE \u09AC\u09BE\u09A3\u09BF\u099C\u09CD\u09AF",
        "pn": "Ka masala sngewbha",
        "hi": "\u092E\u0938\u093E\u0932\u093E \u0935\u094D\u092F\u093E\u092A\u093E\u0930",
        "pa": "\u0A2E\u0A38\u0A3E\u0A32\u0A3E \u0A35\u0A2A\u0A3E\u0A30"
